export class LiveCounter {
  constructor(state, env) { this.state = state; this.env = env; this.tokens = new Map(); }
  janitor() {
    const now = Date.now();
    for (const [k, v] of this.tokens) { if (v.exp < now) this.tokens.delete(k); }
  }
  /* تعداد تونل‌های زنده‌ی یک uuid */
  count(uuid) {
    let n = 0;
    for (const v of this.tokens.values()) { if (v.uuid === uuid) n++; }
    return n;
  }
  /* «نفرات» = IP یکتای تونل‌های زنده — بدون حافظه‌ی تاریخی (ضد بادکردن با چرخش IP) */
  people(uuid) {
    const s = new Set();
    for (const v of this.tokens.values()) { if (v.uuid === uuid && v.ip) s.add(v.ip); }
    return s.size;
  }
  async fetch(req) {
    let url;
    try { url = new URL(req.url); } catch (e) { return new Response('{"error":"bad request"}', { status: 400, headers: { 'content-type': 'application/json' } }); }
    const op = url.pathname;
    const uuid = (url.searchParams.get('uuid') || '').slice(0, 80);
    const ip = (url.searchParams.get('ip') || '').slice(0, 64);
    const rj = function (o, s) { return new Response(JSON.stringify(o), { status: s || 200, headers: { 'content-type': 'application/json' } }); };
    if (op === '/acquire') {
      /* v2.8.1: فقط سقف تونل رد می‌کند؛ «نفرات» هرگز اتصال را رد نمی‌کند */
      const tmax = Math.max(60, Math.min(400, +url.searchParams.get('tmax') || 80));
      this.janitor();
      const n = this.count(uuid);
      if (n >= tmax) return rj({ ok: false, why: 'tunnels', count: n });
      const tok = uuid.slice(0, 8) + '.' + Date.now().toString(36) + '.' + Math.random().toString(36).slice(2, 10);
      this.tokens.set(tok, { uuid: uuid, exp: Date.now() + 95000, ip: ip || '' });
      return rj({ ok: true, token: tok, count: n + 1, people: this.people(uuid) });
    }
    if (op === '/touch') {
      const tok = url.searchParams.get('token') || '';
      const t = this.tokens.get(tok);
      if (t) { t.exp = Date.now() + 95000; if (ip) t.ip = ip; }
      return rj({ ok: true, live: !!t });
    }
    if (op === '/release') {
      this.tokens.delete(url.searchParams.get('token') || '');
      return rj({ ok: true });
    }
    if (op === '/snapshot') {
      this.janitor();
      const c = {}, p = {}, seen = {};
      for (const v of this.tokens.values()) {
        c[v.uuid] = (c[v.uuid] || 0) + 1;
        if (!seen[v.uuid]) seen[v.uuid] = new Set();
        if (v.ip) seen[v.uuid].add(v.ip);
      }
      for (const uu in seen) p[uu] = seen[uu].size;
      return rj({ c: c, p: p });
    }
    if (op === '/reset') {
      if (uuid) { for (const [k, v] of this.tokens) { if (v.uuid === uuid) this.tokens.delete(k); } }
      else this.tokens.clear();
      return rj({ ok: true });
    }
    return rj({ error: 'not found' }, 404);
  }
}

